import { z } from "zod";
export const inputSchema = z.object({ objectionCategory: z.enum(["timing", "cost", "eligibility", "service", "relationship", "competition", "other"]), objection: z.string().trim().max(1_000).optional(), accountType: z.string().trim().min(1).max(100), diseaseFocus: z.string().trim().min(1).max(120), userResponse: z.string().trim().max(2_000).optional(), difficulty: z.enum(["foundational", "intermediate", "advanced"]).default("intermediate") }).strict();
const scoreSchema = z.object({ empathy: z.number().min(0).max(100), curiosity: z.number().min(0).max(100), clarity: z.number().min(0).max(100), nextStep: z.number().min(0).max(100), overall: z.number().min(0).max(100) }).strict();
export const outputSchema = z.object({ objection: z.string().min(1), underlyingConcern: z.string().min(1), tellMeMoreProbes: z.array(z.string().min(1)).min(2).max(5), feelFeltFound: z.object({ feel: z.string().min(1), felt: z.string().min(1), found: z.string().min(1), combinedResponse: z.string().min(1) }).strict(), nextStep: z.string().min(1), avoidSaying: z.array(z.string().min(1)).max(5), analysis: z.object({ scores: scoreSchema, evidence: z.array(z.string().min(1)).max(6), strengths: z.array(z.string().min(1)).max(5), improvements: z.array(z.string().min(1)).max(5) }).strict().nullable(), insights: z.array(z.string().min(1)).max(6) }).strict();
export type ToolInput = z.infer<typeof inputSchema>; export type ToolOutput = z.infer<typeof outputSchema>;
